586  copySubString(const UA_String *src, UA_String *dst,
   587                const UA_NumericRangeDimension *dim) {
   588      if(dim->min > dim->max)
   589          return UA_STATUSCODE_BADINDEXRANGEINVALID;
   590      if(dim->min >= src->length)
   591          return UA_STATUSCODE_BADINDEXRANGENODATA;
   592
   593      size_t length;
   594      if(dim->max < src->length)
   595         length = dim->max - dim->min + 1;
   596      else
   597          length = src->length - dim->min;
   598
   599      UA_StatusCode retval = UA_ByteString_allocBuffer(dst, length);
   600      if(retval != UA_STATUSCODE_GOOD)
   601          return retval;
   602
   603      memcpy(dst->data, &src->data[dim->min], length);
   604      return UA_STATUSCODE_GOOD;
   605  }
